steps.script:
var fast = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/FightResolutionDock/DockFastButton")
if fast != null and fast.is_visible_in_tree() and not fast.disabled:
	fast.pressed.emit()
	return true
return false

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var q = [ov]
while not q.is_empty():
	var n = q.pop_front()
	if n is Label and n.name == "ProgressLabel" and n.is_visible_in_tree():
		return "Step 7 / 9" in str(n.text)
	for c in n.get_children():
		q.append(c)
return "no progress label"

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var q = [ov]
while not q.is_empty():
	var n = q.pop_front()
	if n is RichTextLabel and n.name == "BodyText" and n.is_visible_in_tree():
		return "✚" in str(n.text)
	for c in n.get_children():
		q.append(c)
return "no body text"

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var q = [ov]
while not q.is_empty():
	var n = q.pop_front()
	if n is RichTextLabel and n.name == "BodyText" and n.is_visible_in_tree():
		return "LS" in str(n.text)
	for c in n.get_children():
		q.append(c)
return "no body text"

for c in tree.root.get_children():
	if c is AcceptDialog and c.visible and str(c.title).begins_with("Epic Challenge"):
		return true
var d = tree.root.get_node_or_null("/root/AttackAssignmentDialog")
return d != null and d.visible and str(d.unit_id) == "U_WARBOSS_T"

for c in tree.root.get_children():
	if c is AcceptDialog and c.visible:
		var stack = [c]
		while not stack.is_empty():
			var n = stack.pop_back()
			for ch in n.get_children():
				stack.append(ch)
				if ch is Button and str(ch.text) == "Decline":
					ch.pressed.emit()
					return true
return true

var d = tree.root.get_node_or_null("/root/AttackAssignmentDialog")
if d == null:
	return "no attack dialog"
var wl = d.get_node("Content/WeaponList")
var tl = d.get_node("Content/TargetList")
if wl.item_count == 0 or tl.item_count == 0:
	return "empty lists"
wl.select(0)
wl.item_selected.emit(0)
tl.select(0)
tl.item_selected.emit(0)
d.get_node("Content/ButtonContainer/AllToTargetButton").pressed.emit()
return str(d.unit_id)

var fast = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/FightScrollContainer/FightPanel/FightResolutionDock/DockFastButton")
if fast != null and fast.is_visible_in_tree() and not fast.disabled:
	fast.pressed.emit()
	return true
return false

var ov = tree.root.get_node_or_null("/root/TutorialOverlay")
var q = [ov]
while not q.is_empty():
	var n = q.pop_front()
	if n is RichTextLabel and n.name == "BodyText" and n.is_visible_in_tree():
		return "LS" in str(n.text)
	for c in n.get_children():
		q.append(c)
return "no body text"

var f = tree.root.get_viewport().gui_get_focus_owner()
if f == null:
	return "no focus"
var ov = tree.root.get_node_or_null("/root/Main/AllocationGroupOverlay")
if ov == null or not ov.is_ancestor_of(f):
	return "focus outside card: " + str(f.get_path())
return "Roll Saves" in str(f.text)
